async def save_release(caller: McpCaller, *, id: str | None = None, name: str | None = None, description: str | None = None, version: str | None = None, pipeline: str | None = None, stage: str | None = None, startDate: Any | None = None, targetDate: Any | None = None, createdAt: str | None = None, startedAt: Any | None = None, completedAt: Any | None = None, commitSha: str | None = None) -> Any:
    """Create or update a release. If `id` is provided, updates the existing release; otherwise creates a new one. When creating, `name` and `pipeline` are required. Release status is modeled as the release pipeline stage.

    Args:
        id: Release ID or slug to update. Omit to create a new release.
        name: Release name (required when creating)
        description: Release description
        version: Version identifier
        pipeline: Release pipeline ID, slug, or exact name (required when creating)
        stage: Release stage ID, exact name, or lifecycle type within the release pipeline
        startDate: Estimated start date (ISO YYYY-MM-DD, null to remove)
        targetDate: Estimated completion date (ISO YYYY-MM-DD, null to remove)
        createdAt: Import/create timestamp (ISO DateTime)
        startedAt: Started timestamp (ISO DateTime, null to remove)
        completedAt: Completed timestamp (ISO DateTime, null to remove)
        commitSha: Commit SHA associated with the release
    """
    args: dict[str, Any] = {}
    if id is not None:
        args["id"] = id
    if name is not None:
        args["name"] = name
    if description is not None:
        args["description"] = description
    if version is not None:
        args["version"] = version
    if pipeline is not None:
        args["pipeline"] = pipeline
    if stage is not None:
        args["stage"] = stage
    if startDate is not None:
        args["startDate"] = startDate
    if targetDate is not None:
        args["targetDate"] = targetDate
    if createdAt is not None:
        args["createdAt"] = createdAt
    if startedAt is not None:
        args["startedAt"] = startedAt
    if completedAt is not None:
        args["completedAt"] = completedAt
    if commitSha is not None:
        args["commitSha"] = commitSha
    return await caller.call(SERVER, "save_release", args)

